mod once {
use vstd::{
    atomic_with_ghost,
    cell::pcell::{PCell, PointsTo},
    modes::tracked_static_ref,
    prelude::*,
};

use super::AtomicDataWithOwner;

verus! {

pub const UNINIT: u64 = 0;

pub const OCCUPIED: u64 = 1;

pub const INITED: u64 = 2;

/// A tracked state of a¸ [`Once`] that can be used to ensure that the cell is
/// initialized before accessing its value.
pub tracked enum OnceState<V: 'static> {
    /// The cell is uninitialized.
    Uninit(PointsTo<Option<V>>),
    /// The cell is occupied meaning it is being *written*.
    Occupied,
    /// The cell is initialized with a value and extended with
    /// static lifetime.
    Init(&'static PointsTo<Option<V>>),
}

/// A [`Predicate`] is something you're gonna preserve during the lifetime
/// of any synchronization primitives like [`Once`].
pub trait Predicate<V> {
    spec fn inv(self, v: V) -> bool;
}

/// A trivial predicate that holds for any value.
/// Use with [`OnceImpl`] when no invariant is needed.
pub struct TrivialPred;

impl<V> Predicate<V> for TrivialPred {
    open spec fn inv(self, v: V) -> bool {
        true
    }
}

struct_with_invariants! {
/// A synchronization primitive which can nominally be written to only once.
///
/// This type is a thread-safe [`Once`], and can be used in statics.
/// In many simple cases, you can use [`LazyLock<T, F>`] instead to get the benefits of this type
/// with less effort: `LazyLock<T, F>` "looks like" `&T` because it initializes with `F` on deref!
/// Where OnceLock shines is when LazyLock is too simple to support a given case, as LazyLock
/// doesn't allow additional inputs to its function after you call [`LazyLock::new(|| ...)`].
///
/// A `OnceLock` can be thought of as a safe abstraction over uninitialized data that becomes
/// initialized once written.
///
/// # Examples
///
/// ```rust
/// static MY_ONCE: Once<i32> = Once::new();
///
/// let value = MY_ONCE.get();
/// assert(value.is_some());   // unsatisfied precondition, as MY_ONCE is uninitialized.
/// ```
#[verifier::reject_recursive_types(V)]
pub struct OnceImpl<V: 'static, F: Predicate<V>> {
    cell: PCell<Option<V>>,
    state: vstd::atomic_ghost::AtomicU64<_, OnceState<V>, _>,
    f: Ghost<F>,
}

#[verifier::type_invariant]
pub closed spec fn wf(&self) -> bool {
    invariant on state with (cell, f) is (v: u64, g: OnceState<V>) {
        match g {
            OnceState::Uninit(points_to) => {
                &&& v == UNINIT
                &&& points_to.id() == cell.id()
                &&& points_to.value() is None
            }
            OnceState::Occupied => {
                &&& v == OCCUPIED
            }
            OnceState::Init(points_to) => {
                &&& v == INITED
                &&& points_to.id() == cell.id()
                &&& points_to.value() is Some
                &&& f@.inv(points_to.value()->0)
            }
        }
    }
}

}

#[verifier::external]
unsafe impl<V, F: Predicate<V>> Send for OnceImpl<V, F> {

}

#[verifier::external]
unsafe impl<V, F: Predicate<V>> Sync for OnceImpl<V, F> {

}

impl<V, F: Predicate<V>> OnceImpl<V, F> {
    pub closed spec fn inv(&self) -> F {
        self.f@
    }

    /// Creates a new uninitialized [`Once`].
    pub const fn new(Ghost(f): Ghost<F>) -> (r: Self)
        ensures
            r.wf(),
            r.inv() == f,
    {
        let (cell, Tracked(points_to)) = PCell::new(None);
        let tracked state = OnceState::Uninit(points_to);
        let state = vstd::atomic_ghost::AtomicU64::new(
            Ghost((cell, Ghost(f))),
            UNINIT,
            Tracked(state),
        );

        Self { cell, state, f: Ghost(f) }
    }

    /// Initializes the [`Once`] with the given value `v`.
    pub fn init(&self, v: V)
        requires
            self.inv().inv(v),
            self.wf(),
    {
        let cur_state =
            atomic_with_ghost! {
            &self.state => load(); ghost g => {}
        };

        if cur_state != UNINIT {
            return;
        } else {
            let tracked mut points_to = None;
            let res =
                atomic_with_ghost! {
                &self.state => compare_exchange(UNINIT, OCCUPIED);
                returning res; ghost g => {
                }
            };

            if !res.is_err() {
                let tracked mut points_to = points_to.tracked_unwrap();
                self.cell.replace(Tracked(&mut points_to), Some(v));
                // Extending the permission to static because `OnceLock` is
                // often shared among threads and we want to ensure that
                // the value is accessible globally.
                let tracked static_points_to = tracked_static_ref(points_to);
                // let tracked _ = self.inst.borrow().do_deposit(points_to, points_to, &mut token);
                atomic_with_ghost! {
                    &self.state => store(INITED); ghost g => {
                    }
                }
                return;
            } else {
                // wait or abort.
                return;
            }
        }
    }

    /// Try to get the value stored in the [`Once`]. A [`Option::Some`]
    /// is returned if the cell is initialized; otherwise, [`Option::None`]
    /// is returned.
    pub fn get<'a>(&'a self) -> (r: Option<&'a V>)
        requires
            self.wf(),
        ensures
            self.wf(),
            r matches Some(res) ==> self.inv().inv(*res),
    {
        let tracked mut points_to = None;
        let res =
            atomic_with_ghost! {
            &self.state => load(); ghost g => {
            }
        };

        if res == INITED {
            let tracked points_to = points_to.tracked_unwrap();
            let tracked static_points_to = tracked_static_ref(points_to);

            self.cell.borrow(Tracked(static_points_to)).as_ref()
        } else {
            None
        }
    }
}

/// A `Once` that combines some data with a permission to access it.
///
/// This type alias automatically lifts the target value `V` into
/// a wrapper [`AtomicDataWithOwner<V, Own>`] where `Own` is the
/// permission type so that we can reason about non-trivial runtime
/// properties in verification.
pub type Once<V, Own, F> = OnceImpl<AtomicDataWithOwner<V, Own>, F>;

} // verus!
} // mod once

pub use once::*;

#![allow(unused_imports)]

use super::super::prelude::*;
use super::CellId;
use super::pcell_maybe_uninit::*;
use core::cell::UnsafeCell;
use core::marker::PhantomData;
use core::mem::ManuallyDrop;

use verus as verus_;
verus_! {

/**
`PCell<T>` (which stands for "permissioned cell") is the most primitive Verus `Cell` type.
It can often be used as a replacement for Rust's [`UnsafeCell`], and it can serve
as a basis for verifying many other interior-mutable types
(e.g., [`InvCell`](super::invcell::InvCell),
[`RefCell`](https://github.com/verus-lang/verus/blob/main/examples/state_machines/tutorial/ref_cell.rs)).

`PCell` uses a _ghost permission token_ similar to [`simple_pptr::PPtr`](super::super::simple_pptr) -- see the [`simple_pptr::PPtr`](super::super::simple_pptr)
documentation for the basics.
For `PCell`, the associated type of the permission token is [`PointsTo`].

If you want a cell that can be optionally initialized, see [`pcell_maybe_uninit::PCell`](super::pcell_maybe_uninit::PCell).

### Differences from `PPtr`.

Whereas [`simple_pptr::PPtr`](super::super::simple_pptr) represents a fixed address in memory,
a `PCell` has _no_ fixed address because a `PCell` might be moved.
As such, the [`pcell.id()`](PCell::id) does not correspond to a memory address; rather,
it is a unique identifier that is fixed for a given cell, even when it is moved.

The arbitrary ID given by [`pcell.id()`](PCell::id) is of type [`CellId`].
Despite the fact that it is, in some ways, "like a pointer", note that
`CellId` does not support any meangingful "pointer arithmetic,"
has no concept of a "null ID",
and has no runtime representation.

### Differences from [`UnsafeCell`](core::cell::UnsafeCell).

Though inspired by `UnsafeCell`, `PCell` is not quite the same thing.
The differences include:

 * `PCell<T>` **does not call the destructor of `T` when it goes out of scope**.
   Technically speaking, `PCell<T>` is actually implemented via
   `ManuallyDrop<UnsafeCell<T>>`. This is because dropping the contents is unsound
   if the `PointsTo<T>` is not also reclaimed. To drop a `PCell<T>` without leaking,
   call [`into_inner`](Self::into_inner) with the corresponding `PointsTo`.

 * `PCell<T>` _always_ implements `Send` and `Sync`, regardless of the type `T`.
   Instead, it is `PointsTo<T>` where the marker traits matter.
   (It doesn't matter if you move the bytes to another thread if you can't access them.)

### Example

```rust,ignore
use vstd::prelude::*;
use vstd::cell::pcell as pc;

verus! {

fn example_pcell() {
    let (cell, Tracked(mut points_to)) = pc::PCell::new(5);

    assert(points_to.id() == cell.id());
    assert(points_to.value() == 5);

    cell.write(Tracked(&mut points_to), 17);

    assert(points_to.id() == cell.id());
    assert(points_to.value() == 17);

    let x = cell.into_inner(Tracked(points_to));
    assert(x == 17);
}

} // verus!
```
*/

#[verifier::external_body]
#[verifier::accept_recursive_types(T)]
pub struct PCell<T: ?Sized> {
    // Unlike UnsafeCell, a PCell's drop should NOT drop the contents (since we do not have
    // the permissions to access the contents). To prevent this, we need to use ManuallyDrop
    ucell: ManuallyDrop<UnsafeCell<T>>,
}

/// `PCell` is _always_ safe to `Send` or `Sync`. Rather, it is the [`PointsTo`] object where `Send` and `Sync` matter.
/// (It doesn't matter if you move the bytes to another thread if you can't access them.)
#[verifier::external]
unsafe impl<T: ?Sized> Sync for PCell<T> { }
#[verifier::external]
unsafe impl<T: ?Sized> Send for PCell<T> { }

/// Permission object associated with a [`PCell<T>`].
///
/// See the documentation of [`PCell<T>`] for more information.
#[verifier::external_body]
#[verifier::reject_recursive_types_in_ground_variants(T)]
pub tracked struct PointsTo<T: ?Sized> {
    // Through PhantomData we inherit the Send/Sync marker traits
    phantom: PhantomData<T>,
    no_copy: NoCopy,
}

impl<T: ?Sized> PointsTo<T> {
    /// The [`CellId`] of the [`PCell`] this permission is associated with.
    pub uninterp spec fn id(&self) -> CellId;

    // To support ?Sized, the `.value()` has to return a reference.
    // This restriction is enforced by rust even in spec code.

    /// The contents of the cell.
    pub uninterp spec fn value(&self) -> &T;

    /// Guarantees that two permissions can not be associated with the same `CellId`.
    pub axiom fn is_exclusive(tracked &mut self, tracked other: & PointsTo<T>)
    ensures
        *final(self) == *old(self),
        final(self).id() != other.id(),
    ;
}

impl<T: ?Sized> PCell<T> {
    /// A unique ID for the cell.
    pub uninterp spec fn id(&self) -> CellId;

    /// Construct a new `PCell` with a fresh [`id`](Self::id).
    #[inline(always)]
    #[verifier::external_body]
    pub const fn new(v: T) -> (pt: (PCell<T>, Tracked<PointsTo<T>>))
        where T: Sized
        ensures
            pt.1@.id() == pt.0.id() && pt.1@.value() == v
        opens_invariants none
        no_unwind
    {
        let p = PCell { ucell: ManuallyDrop::new(UnsafeCell::new(v)) };
        (p, Tracked::assume_new())
    }

    #[inline(always)]
    #[verifier::external_body]
    pub fn borrow<'a>(&'a self, Tracked(perm): Tracked<&'a PointsTo<T>>) -> (v: &'a T)
        requires
            self.id() == perm.id(),
        ensures
            v == perm.value(),
        opens_invariants none
        no_unwind
    {
        // SAFETY: We can take a shared reference since we have the shared PointsTo
        unsafe { &(*(*self.ucell).get()) }
    }

    #[inline(always)]
    #[verifier::external_body]
    pub fn borrow_mut<'a>(&'a self, Tracked(perm): Tracked<&'a mut PointsTo<T>>) -> (v: &'a mut T)
        requires
            self.id() == perm.id(),
        ensures
            &*v == old(perm).value(),
            &*final(v) == final(perm).value(),
            final(perm).id() == self.id(),
        opens_invariants none
        no_unwind
    {
        // SAFETY: We can take a mutable reference since we have the mutable PointsTo
        unsafe { &mut (*(*self.ucell).get()) }
    }

    #[inline(always)]
    #[verifier::external_body]
    pub fn into_inner(self, Tracked(perm): Tracked<PointsTo<T>>) -> (v: T)
        where T: Sized
        requires
            self.id() == perm.id(),
        ensures
            v == *perm.value(),
        opens_invariants none
        no_unwind
    {
        // Note that for an UnsafeCell, intro_inner is a safe operation, whereas for PCell,
        // we require the Tracked permission.
        ManuallyDrop::into_inner(self.ucell).into_inner()
    }

    ////// Trusted core ends here

    #[inline(always)]
    pub fn replace(&self, Tracked(perm): Tracked<&mut PointsTo<T>>, in_v: T) -> (out_v: T)
        where T: Sized
        requires
            self.id() == old(perm).id(),
        ensures
            final(perm).id() == old(perm).id(),
            *final(perm).value() == in_v,
            out_v == *old(perm).value(),
        opens_invariants none
        no_unwind
    {
        let mut v = in_v;
        core::mem::swap(&mut v, self.borrow_mut(Tracked(perm)));
        v
    }

    #[inline(always)]
    pub fn write(&self, Tracked(perm): Tracked<&mut PointsTo<T>>, in_v: T)
        where T: Sized
        requires
            self.id() == old(perm).id()
        ensures
            final(perm).id() == old(perm).id(),
            *final(perm).value() == in_v,
        opens_invariants none
        no_unwind
    {
        let _out = self.replace(Tracked(&mut *perm), in_v);
    }

